import React from "react";

/*
 * Wedding-day sets, drawn in 1080×1920 scene space: the lake palace (Day title), the jharokha
 * dressing room (Sehra), the baraat street, the floral jaimaal wall, the lunch canopy, the palace
 * gate (Vidai) and the reception ballroom. Pieces are split by depth so scenes can parallax them.
 */

/* ───────────────────────── shared architecture helpers ───────────────────────── */

/** Onion dome sitting on (cx, by), width w, height h, with a finial. */
export const Dome: React.FC<{ cx: number; by: number; w: number; h: number; fill: string; finial?: string; line?: string; shade?: string }> = ({
  cx,
  by,
  w,
  h,
  fill,
  finial,
  line,
  shade,
}) => (
  <g>
    <path
      d={`M${cx - w / 2} ${by} C${cx - w * 0.66} ${by - h * 0.32} ${cx - w * 0.46} ${by - h * 0.72} ${cx} ${by - h} C${cx + w * 0.46} ${by - h * 0.72} ${cx + w * 0.66} ${by - h * 0.32} ${cx + w / 2} ${by} Z`}
      fill={fill}
    />
    {shade ? (
      <path
        d={`M${cx} ${by - h} C${cx + w * 0.46} ${by - h * 0.72} ${cx + w * 0.66} ${by - h * 0.32} ${cx + w / 2} ${by} L${cx + w * 0.16} ${by} C${cx + w * 0.26} ${by - h * 0.35} ${cx + w * 0.2} ${by - h * 0.72} ${cx} ${by - h} Z`}
        fill={shade}
        opacity={0.45}
      />
    ) : null}
    {line ? (
      <path
        d={`M${cx - w * 0.52} ${by - h * 0.1} C${cx - w * 0.3} ${by - h * 0.16} ${cx + w * 0.3} ${by - h * 0.16} ${cx + w * 0.52} ${by - h * 0.1}`}
        fill="none"
        stroke={line}
        strokeWidth={1.4}
        opacity={0.7}
      />
    ) : null}
    {finial ? (
      <g>
        <path d={`M${cx} ${by - h} L${cx} ${by - h - h * 0.3}`} stroke={finial} strokeWidth={Math.max(1.2, w * 0.03)} />
        <circle cx={cx} cy={by - h - h * 0.12} r={Math.max(2, w * 0.045)} fill={finial} />
      </g>
    ) : null}
  </g>
);

/** Pointed (Mughal) arch opening: rectangle below `spring`, pointed arch above, apex at `apex`. */
export const archPath = (x: number, w: number, spring: number, apex: number, base: number): string => {
  const cx = x + w / 2;
  const h = spring - apex;
  return `M${x} ${base} L${x} ${spring} C${x} ${spring - h * 0.62} ${cx - w * 0.2} ${apex + h * 0.22} ${cx} ${apex} C${cx + w * 0.2} ${apex + h * 0.22} ${x + w} ${spring - h * 0.62} ${x + w} ${spring} L${x + w} ${base} Z`;
};

/** Multifoil (cusped) arch opening — lobes along a pointed arch. */
export const cuspedArchPath = (x: number, w: number, spring: number, apex: number, base: number, lobes = 7): string => {
  const cx = x + w / 2;
  const h = spring - apex;
  // left half control polygon of the pointed arch
  const P0: [number, number] = [x, spring];
  const P1: [number, number] = [x, spring - h * 0.62];
  const P2: [number, number] = [cx - w * 0.2, apex + h * 0.22];
  const P3: [number, number] = [cx, apex];
  const bez = (t: number, a: number[], b: number[], c: number[], d: number[]) => {
    const u = 1 - t;
    return [
      u * u * u * a[0] + 3 * u * u * t * b[0] + 3 * u * t * t * c[0] + t * t * t * d[0],
      u * u * u * a[1] + 3 * u * u * t * b[1] + 3 * u * t * t * c[1] + t * t * t * d[1],
    ];
  };
  const leftPts: number[][] = [];
  for (let i = 0; i <= lobes; i++) leftPts.push(bez(i / lobes, P0, P1, P2, P3));
  const rightPts = leftPts
    .slice(0, -1)
    .reverse()
    .map(([px, py]) => [2 * cx - px, py]);
  const pts = [...leftPts, ...rightPts];
  let d = `M${x} ${base} L${x} ${spring}`;
  for (let i = 1; i < pts.length; i++) {
    const [ax, ay] = pts[i - 1];
    const [bx, by] = pts[i];
    const r = Math.hypot(bx - ax, by - ay) * 0.56;
    d += ` A${r.toFixed(1)} ${r.toFixed(1)} 0 0 1 ${bx.toFixed(1)} ${by.toFixed(1)}`;
  }
  d += ` L${x + w} ${base} Z`;
  return d;
};

/** Small open pavilion (chhatri): plinth, four pillars, slab, dome. */
export const Chhatri: React.FC<{ cx: number; by: number; w: number; fill: string; shade: string; glow?: string }> = ({ cx, by, w, fill, shade, glow }) => {
  const ph = w * 0.7;
  return (
    <g>
      {glow ? <rect x={cx - w * 0.4} y={by - ph} width={w * 0.8} height={ph} fill={glow} /> : null}
      <rect x={cx - w / 2} y={by - 6} width={w} height={6} fill={shade} />
      {[-0.42, -0.14, 0.14, 0.42].map((k) => (
        <rect key={k} x={cx + k * w - w * 0.045} y={by - ph} width={w * 0.09} height={ph} fill={fill} />
      ))}
      <path d={`M${cx - w * 0.62} ${by - ph} L${cx + w * 0.62} ${by - ph} L${cx + w * 0.5} ${by - ph - w * 0.12} L${cx - w * 0.5} ${by - ph - w * 0.12} Z`} fill={shade} />
      <Dome cx={cx} by={by - ph - w * 0.12} w={w * 0.82} h={w * 0.62} fill={fill} finial={shade} />
    </g>
  );
};

/* ───────────────────────── Day title: lake palace ───────────────────────── */

/**
 * A lake palace facade seen across water at dawn: central tower with a great dome, flanking
 * towers, two storeys of arched windows (lit warm), chhatris on the roofline. Base at `base`.
 */
export const LakePalace: React.FC<{ base: number; wall: string; shade: string; trim: string; lit: string; litOpacity?: number }> = ({
  base: B,
  wall,
  shade,
  trim,
  lit,
  litOpacity = 1,
}) => {
  const winRow = (y: number, x0: number, x1: number, n: number, w: number, h: number) =>
    new Array(n).fill(0).map((_, i) => {
      const x = x0 + ((x1 - x0) * (i + 0.5)) / n - w / 2;
      return (
        <g key={`${y}-${i}`}>
          <path d={archPath(x - 5, w + 10, y + h * 0.45, y - 8, y + h + 4)} fill={shade} opacity={0.55} />
          <path d={archPath(x, w, y + h * 0.45, y, y + h)} fill={lit} opacity={litOpacity * (0.72 + ((i * 7) % 5) * 0.07)} />
        </g>
      );
    });
  const merlons = (x0: number, x1: number, y: number, step = 16) =>
    new Array(Math.floor((x1 - x0) / step)).fill(0).map((_, i) => (
      <path
        key={`${y}m${i}`}
        d={`M${x0 + i * step + 3} ${y} L${x0 + i * step + 3} ${y - 9} Q${x0 + i * step + step / 2} ${y - 16} ${x0 + (i + 1) * step - 3} ${y - 9} L${x0 + (i + 1) * step - 3} ${y} Z`}
        fill={wall}
      />
    ));
  const band = (x: number, y: number, w: number) => <rect x={x} y={y} width={w} height={3} fill={trim} opacity={0.85} />;
  return (
    <g>
      {/* ghat steps */}
      <rect x={60} y={B - 34} width={960} height={34} fill={shade} />
      <rect x={60} y={B - 20} width={960} height={2} fill={trim} opacity={0.5} />
      <rect x={90} y={B - 50} width={900} height={16} fill={wall} />
      {band(90, B - 50, 900)}
      {/* main block */}
      {merlons(170, 910, B - 300)}
      <rect x={170} y={B - 300} width={740} height={250} fill={wall} />
      {band(170, B - 300, 740)}
      {band(170, B - 178, 740)}
      <rect x={170} y={B - 174} width={740} height={8} fill={shade} opacity={0.5} />
      {/* corner bastions and the shaded half, for volume */}
      <rect x={170} y={B - 300} width={30} height={250} fill={shade} opacity={0.25} />
      <rect x={880} y={B - 300} width={30} height={250} fill={shade} opacity={0.55} />
      <rect x={540} y={B - 300} width={370} height={250} fill={shade} opacity={0.12} />
      {/* jharokha balconies on the main block */}
      {[250, 830].map((x) => (
        <g key={x}>
          <path d={`M${x - 46} ${B - 196} L${x + 46} ${B - 196} L${x + 34} ${B - 176} L${x - 34} ${B - 176} Z`} fill={shade} />
          <rect x={x - 46} y={B - 200} width={92} height={4} fill={trim} />
          <path d={archPath(x - 30, 60, B - 250, B - 282, B - 200)} fill={lit} opacity={litOpacity * 0.85} />
          <rect x={x - 30} y={B - 223} width={60} height={3} fill={shade} />
          <Dome cx={x} by={B - 290} w={80} h={42} fill={wall} shade={shade} finial={trim} />
          <rect x={x - 42} y={B - 292} width={84} height={4} fill={shade} />
        </g>
      ))}
      {winRow(B - 160, 310, 770, 7, 34, 70)}
      {winRow(B - 280, 340, 740, 6, 28, 60)}
      {/* flanking towers */}
      {[300, 780].map((x) => (
        <g key={x}>
          <rect x={x - 58} y={B - 420} width={116} height={124} fill={wall} />
          <rect x={x + 18} y={B - 420} width={40} height={124} fill={shade} opacity={0.3} />
          {band(x - 58, B - 330, 116)}
          <rect x={x - 66} y={B - 426} width={132} height={10} fill={shade} />
          {band(x - 66, B - 426, 132)}
          <path d={archPath(x - 20, 40, B - 372, B - 398, B - 336)} fill={lit} opacity={litOpacity * 0.9} />
          <Dome cx={x} by={B - 426} w={100} h={84} fill={wall} shade={shade} finial={trim} line={trim} />
        </g>
      ))}
      {/* central tower + great dome */}
      {merlons(420, 660, B - 470, 20)}
      <rect x={420} y={B - 470} width={240} height={172} fill={wall} />
      <rect x={560} y={B - 470} width={100} height={172} fill={shade} opacity={0.22} />
      <rect x={410} y={B - 478} width={260} height={12} fill={shade} />
      {band(410, B - 478, 260)}
      {band(420, B - 312, 240)}
      {[462, 540, 618].map((x, i) => (
        <g key={x}>
          <path d={archPath(x - 27, 54, B - 404, B - 446, B - 322)} fill={shade} opacity={0.5} />
          <path d={archPath(x - 21, 42, B - 404, B - 438, B - 328)} fill={lit} opacity={litOpacity * (i === 1 ? 1 : 0.85)} />
        </g>
      ))}
      <rect x={456} y={B - 524} width={168} height={46} fill={wall} />
      <rect x={570} y={B - 524} width={54} height={46} fill={shade} opacity={0.3} />
      {band(456, B - 524, 168)}
      <Dome cx={540} by={B - 524} w={200} h={170} fill={wall} shade={shade} finial={trim} line={trim} />
      {/* roofline chhatris */}
      {[200, 880, 385, 695].map((x, i) => (
        <Chhatri key={x} cx={x} by={B - 300} w={i < 2 ? 60 : 46} fill={wall} shade={shade} />
      ))}
    </g>
  );
};
